  text-size-adjust: 100%;
}
body {
  margin: 0;
  font-family: var(--font-body);
  font-size: calc(var(--t-body-size) * var(--text-scale));
  line-height: var(--t-body-line);
  font-weight: var(--t-body-weight);
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
/* Respect iOS Dynamic Type when the app runs on an iPhone. */
@supports (font: -apple-system-body) {
  html.dynamic-type {
    /* biome-ignore lint/a11y/useGenericFontNames: a system text-style keyword (Dynamic Type), not a family. */
    font: -apple-system-body;
  }
}
img,
svg {
  display: block;
  max-width: 100%;
}
button,
input,
textarea,
select {
  font: inherit;
  color: inherit;
}
